'use strict';

// Ergänzung: bestehende Aufgaben und deren Speicherschlüssel bleiben erhalten.
(() => {
  const text = (title, content) => ({ title, type: 'text', content });
  const table = (title, columns, rows) => ({ title, type: 'table', columns, rows });
  const part = (id, operator, prompt, points, hint, modelAnswer) => ({
    id, label: '', type: 'freeText', operator, prompt: `${prompt} (${points} BE)`,
    points, hint, modelAnswer, checking: { type: 'selfAssessment' }
  });
  const tasks = [
    {
      id: 'fokus-hofmann', title: '1. Wasser zerlegen im Hofmann-Apparat (25 BE)',
      shortTitle: 'Hofmann-Apparat', image: '../../assets/solarlabor.png',
      description: 'Gase zuordnen, Elektrodenreaktionen formulieren und Versuchsdaten auswerten · 25 BE',
      context: 'Eine Lerngruppe untersucht die Wasserzersetzung. Bearbeiten Sie die Aufgaben anhand von Material 1 und 2. Schreiben Sie auch bei Rechnungen Ihren Lösungsweg auf. H⁺ darf als vereinfachte Schreibweise für hydratisierte Protonen verwendet werden.',
      materials: [
        text('Material 1: Versuchsaufbau und Bedingungen', 'Ein Hofmann-Apparat enthält mit wenig Schwefelsäure angesäuertes Wasser und reaktionsträge Platinelektroden. Gasraum A liegt über der mit dem Minuspol verbundenen Elektrode, Gasraum B über der mit dem Pluspol verbundenen Elektrode. Die Gase werden getrennt aufgefangen. Die Säure erhöht die Leitfähigkeit; Sulfat-Ionen werden im betrachteten Modell nicht umgesetzt. Alle Volumina werden bei gleicher Temperatur und gleichem Druck verglichen. Nach einer Anlaufphase wird die Volumenmessung auf null gesetzt.'),
        table('Material 2: Gasvolumina – didaktisch modellierte Daten', ['Zeit ab Messbeginn / min', 'Gasraum A / mL', 'Gasraum B / mL'], [['0', '0', '0'], ['2', '12', '6'], ['4', '24', '12'], ['6', '36', '18']])
      ],
      subtasks: [
        part('fokus-hofmann-1', 'Beschreiben', 'Sie die Entwicklung beider Gasvolumina und ihr Verhältnis anhand von Material 2. Trennen Sie die Beschreibung von einer Erklärung.', 4, 'Vergleichen Sie gleiche Zeitabschnitte und bilden Sie einen Quotienten.', 'Beide Volumina steigen gleichmäßig (1 BE). In 2 min kommen in A jeweils 12 mL und in B jeweils 6 mL hinzu (2 BE). Zu jedem Messzeitpunkt nach Beginn gilt V(A) : V(B) = 2 : 1 (1 BE).'),
        part('fokus-hofmann-2', 'Ordnen', 'Sie beiden Gasräumen das Gas sowie die Bezeichnung Anode oder Kathode zu. Begründen Sie die Elektrodenzuordnung mit der Elektronenaufnahme bzw. -abgabe.', 5, 'Elektrodennamen werden über den Reaktionstyp definiert. Nutzen Sie zusätzlich die Polung.', 'A: Wasserstoff, Kathode am Minuspol; hier nehmen Wasserstoff-Ionen Elektronen auf (2 BE). B: Sauerstoff, Anode am Pluspol; hier wird Wasser oxidiert und gibt Elektronen ab (2 BE). Anode bedeutet immer Oxidation, Kathode immer Reduktion (1 BE).'),
        part('fokus-hofmann-3', 'Formulieren', 'Sie die beiden Teilgleichungen in saurer Lösung und die Gesamtgleichung der Wasserzersetzung. Gleichen Sie Atome und Ladungen aus.', 6, 'Gleichen Sie zunächst die einzelnen Halbgleichungen aus und bringen Sie die Elektronenzahlen auf denselben Wert.', 'Kathode: 4 H⁺ + 4 e⁻ → 2 H₂ (2 BE). Anode: 2 H₂O → O₂ + 4 H⁺ + 4 e⁻ (2 BE). Gesamt: 2 H₂O → 2 H₂ + O₂ (2 BE). Gleichwertig mit Oxonium-Ionen: Kathode 4 H₃O⁺ + 4 e⁻ → 2 H₂ + 4 H₂O; Anode 6 H₂O → O₂ + 4 H₃O⁺ + 4 e⁻. Proportionale Koeffizienten sind zulässig.'),
        part('fokus-hofmann-4', 'Erklären', 'Sie das Gasvolumenverhältnis mithilfe der Gesamtgleichung. Berechnen Sie anschließend die Volumina nach 10 min bei unverändertem Verlauf.', 5, 'Verbinden Sie Stoffmengenverhältnis und Gasvolumenverhältnis. Nutzen Sie für die Rechnung die Tabelle, auch wenn Ihre Gleichung noch unsicher ist.', 'Aus zwei Wassermolekülen entstehen zwei Wasserstoffmoleküle und ein Sauerstoffmolekül; n(H₂) : n(O₂) = 2 : 1 (2 BE). Bei gleichem Druck und gleicher Temperatur entspricht dem das Volumenverhältnis 2 : 1 (1 BE). A: 6 mL/min · 10 min = 60 mL; B: 3 mL/min · 10 min = 30 mL (je 1 BE einschließlich Ansatz).'),
        part('fokus-hofmann-5', 'Beurteilen', 'Sie die Aussage: „Die Schwefelsäure liefert die Energie für die Gasbildung; deshalb müsste die Gasbildung nach Abschalten der Spannungsquelle dauerhaft weitergehen.“ Beziehen Sie die Rolle der Säure und die Energieumwandlung ein.', 5, 'Unterscheiden Sie die Leitfähigkeit einer Lösung von der Energiequelle des Prozesses.', 'Die Aussage ist falsch (1 BE). Die Säure liefert bewegliche Ionen und verbessert die Leitfähigkeit (1 BE); sie wird im Modell insgesamt nicht verbraucht (1 BE). Die Spannungsquelle liefert elektrische Energie, die bei der Wasserzersetzung in chemische Energie überführt wird (1 BE). Ohne Energiezufuhr findet keine dauerhafte weitere Elektrolyse statt; bereits gebildete Gasblasen können noch aufsteigen (1 BE).')
      ]
    },
    {
      id: 'fokus-pem', title: '2. Wasserstoff als Energiespeicher: PEM-Brennstoffzelle (25 BE)',
      shortTitle: 'PEM-Brennstoffzelle', image: '../../assets/wasserstoff.png',
      description: 'Teilchenwege, Elektrodenreaktionen und Energieverluste erklären · 25 BE',
      context: 'Eine Schule speichert einen Teil ihrer Solarenergie in Wasserstoff. Später versorgt eine PEM-Brennstoffzelle eine Lampe. Verwenden Sie Material 1 und 2. Betrachtet wird die Brennstoffzelle im Betrieb, nicht ein Elektrolyseur.',
      materials: [
        text('Material 1: Aufbau der PEM-Brennstoffzelle', 'Wasserstoff wird kontinuierlich der linken, Sauerstoff der rechten Elektrode zugeführt. Beide Elektroden besitzen einen Platin-Katalysator und sind außen über eine Lampe verbunden. Dazwischen liegt eine feuchte Protonenaustauschmembran (PEM). Sie ist für H⁺ leitfähig und im Modell für Elektronen und die zugeführten Gase undurchlässig. Wasser wird auf der Sauerstoffseite abgeführt. Es findet keine Verbrennung mit Flamme statt.'),
        table('Material 2: Energiebilanz – didaktisch modellierte Daten', ['Größe für einen vollständigen Speicherzyklus', 'Energie'], [['Elektrische Energie für die Elektrolyse', '100 kJ'], ['Im erzeugten Wasserstoff gespeicherte chemische Energie', '70 kJ'], ['Von der Brennstoffzelle abgegebene elektrische Energie', '35 kJ']]),
        text('Hinweis zu Material 2', 'Die Energien beziehen sich auf dieselbe Wasserstoffmenge und dieselbe energetische Bezugsbasis. Der Wasserstoff wird vollständig umgesetzt. Weitere Speicher- und Transportverluste werden vernachlässigt. Wirkungsgrad η = nutzbare abgegebene Energie / zugeführte Energie; für Prozentangaben mit 100 % multiplizieren.')
      ],
      subtasks: [
        part('fokus-pem-1', 'Erläutern', 'Sie die Wege von Elektronen und Protonen zwischen den Elektroden in Material 1 und die Funktion der Membran. Gehen Sie auch auf den Verbraucher ein.', 5, 'Verfolgen Sie beide Ladungsträger getrennt. Überlegen Sie, wodurch die Lampe mit Energie versorgt wird.', 'An der Wasserstoffseite entstehen Protonen und Elektronen (1 BE). Elektronen fließen außen von der Wasserstoff- zur Sauerstoffelektrode durch die Lampe und übertragen dabei elektrische Energie (2 BE). H⁺ wandern durch die Membran zur Sauerstoffseite (1 BE). Die Membran ermöglicht den inneren Ladungsausgleich und trennt zugleich die Gase; sie sperrt den direkten Elektronenweg (1 BE).'),
        part('fokus-pem-2', 'Formulieren', 'Sie beide Teilgleichungen und die Gesamtgleichung der PEM-Brennstoffzelle mit H⁺ als Protonenschreibweise.', 6, 'Prüfen Sie für jede Elektrode Stoff- und Ladungsbilanz. Im Gesamtprozess dürfen keine Elektronen übrig bleiben.', 'Anode: 2 H₂ → 4 H⁺ + 4 e⁻ (2 BE). Kathode: O₂ + 4 H⁺ + 4 e⁻ → 2 H₂O (2 BE). Gesamt: 2 H₂ + O₂ → 2 H₂O (2 BE). Proportionale Koeffizienten sind gleichwertig. Freie O²⁻-Ionen sind keine in der feuchten PEM-Zelle transportierten Teilchen.'),
        part('fokus-pem-3', 'Vergleichen', 'Sie PEM-Brennstoffzelle und Hofmann-Apparat hinsichtlich Energieumwandlung, Polung der Anode und Polung der Kathode. Erklären Sie, was die Elektrodennamen bei beiden gemeinsam bedeuten.', 5, 'Legen Sie dieselben Vergleichskriterien für beide Geräte an. Unterscheiden Sie Polung und Reaktionsart.', 'Brennstoffzelle: chemische → elektrische Energie; Hofmann-Apparat: elektrische → chemische Energie (2 BE). In der Brennstoffzelle ist die Anode negativ und die Kathode positiv, bei der Elektrolyse ist die Anode positiv und die Kathode negativ (2 BE). Gemeinsam: Oxidation an der Anode, Reduktion an der Kathode (1 BE).'),
        part('fokus-pem-4', 'Berechnen', 'Sie anhand von Material 2 die Wirkungsgrade von Elektrolyseur, Brennstoffzelle und gesamtem Speicherzyklus. Geben Sie jeweils den Ansatz an.', 6, 'Achten Sie auf die zugeführte Energie des jeweiligen Teilsystems. Für die Brennstoffzelle ist das nicht die ursprüngliche elektrische Energie.', 'Elektrolyseur: η = 70 kJ / 100 kJ = 0,70 = 70 % (2 BE). Brennstoffzelle: η = 35 kJ / 70 kJ = 0,50 = 50 % (2 BE). Gesamtsystem: η = 35 kJ / 100 kJ = 0,35 = 35 %, auch 0,70 · 0,50 = 0,35 (2 BE). Jeweils 1 BE für den Ansatz und 1 BE für das Ergebnis.'),
        part('fokus-pem-5', 'Beurteilen', 'Sie die Aussage: „Weil wieder Wasser entsteht, erhält man die gesamte eingesetzte elektrische Energie zurück.“ Belegen Sie Ihr Urteil mit Material 2 und nennen Sie einen möglichen Nutzen des Speicherzyklus.', 3, 'Unterscheiden Sie einen Stoffkreislauf von einer Energiebilanz. Denken Sie an unterschiedliche Zeiten von Erzeugung und Bedarf.', 'Die Aussage ist falsch: Von 100 kJ werden nur 35 kJ als elektrische Energie zurückgewonnen (1 BE). Die übrige Energie wird vor allem als Wärme an die Umgebung abgegeben; Stoffkreislauf bedeutet keine verlustfreie Rückgewinnung nutzbarer Energie (1 BE). Trotzdem kann die Speicherung sinnvoll sein, um überschüssige Solarenergie zeitversetzt zu nutzen (1 BE).')
      ]
    },
    {
      id: 'fokus-korrosion', title: '3. Warum rostet ein Stahlgeländer? (25 BE)',
      shortTitle: 'Säure- und Sauerstoffkorrosion', image: '../../assets/sauerstoff.png',
      description: 'Versuchsbefunde deuten und zwei Korrosionsarten vergleichen · 25 BE',
      context: 'An einem Stahlgeländer treten nach einem feuchten Winter Roststellen auf. Modellversuche sollen die Bedingungen der Korrosion klären. Stahl wird vereinfacht als Eisen betrachtet.',
      materials: [
        text('Material 1: Vergleichsversuch', 'Vier identische, gereinigte Eisennägel werden gleich lange bei gleicher Temperatur untersucht. A liegt in trockener Luft. B liegt vollständig in sauerstofffreiem Wasser unter Schutzgas. C liegt in neutralem, belüftetem Wasser. D liegt in neutraler, belüfteter Natriumchlorid-Lösung. Bei C und D sind die Anfangskonzentration des gelösten Sauerstoffs und die benetzte Nagelfläche gleich. Alle anderen Bedingungen sind möglichst gleich. Die qualitative Beobachtung ist didaktisch modelliert; eine Korrosionsrate wurde nicht gemessen.'),
        table('Material 2: Beobachtungen nach zwei Tagen', ['Ansatz', 'Beobachtung'], [['A', 'Kein sichtbarer Rost'], ['B', 'Kein sichtbarer Rost'], ['C', 'Rostbildung'], ['D', 'Stärkere sichtbare Rostbildung als bei C']]),
        text('Material 3: Zwei elektrochemische Modelle', 'Modell I: Ein neutraler, sauerstoffhaltiger Wasserfilm bedeckt die Eisenoberfläche. An räumlich getrennten Bereichen finden Metallauflösung und Sauerstoffreduktion statt. Zunächst entstehen Fe²⁺- und OH⁻-Ionen. Modell II: Eisen befindet sich in sauerstofffreier, verdünnter Salzsäure. Dabei entstehen Fe²⁺-Ionen und Wasserstoffgas. Beide Modelle betrachten ungeschütztes Eisen ohne Passivierung. Rost umfasst verschiedene Eisen(III)-Verbindungen und besitzt keine einheitliche Summenformel.')
      ],
      subtasks: [
        part('fokus-korrosion-1', 'Beschreiben', 'Sie die Ergebnisse in Material 2, ohne sie bereits zu erklären.', 3, 'Benennen Sie die Gruppen ohne sichtbare Veränderung und vergleichen Sie die beiden übrigen Ansätze.', 'In A und B ist kein sichtbarer Rost erkennbar (1 BE). In C bildet sich Rost (1 BE). D zeigt stärkere sichtbare Rostbildung als C (1 BE). Aus den qualitativen Angaben lässt sich keine zahlenmäßige Korrosionsrate ableiten.'),
        part('fokus-korrosion-2', 'Erklären', 'Sie die Unterschiede zwischen A, B und C sowie zwischen C und D mithilfe der Versuchsbedingungen. Begrenzen Sie Ihre Aussage auf die hier untersuchte Sauerstoffkorrosion.', 5, 'Prüfen Sie jeweils, welcher Bestandteil oder welche Eigenschaft des leitfähigen Wasserfilms verändert wird.', 'A fehlt der Wasserfilm als Elektrolyt (1 BE). B fehlt gelöster Sauerstoff für die kathodische Reaktion des betrachteten Modells (1 BE). C enthält Wasser und Sauerstoff, sodass die gekoppelte Metalloxidation und Sauerstoffreduktion ablaufen kann (1 BE). Die Ionen in D erhöhen die elektrische Leitfähigkeit des Wasserfilms und erleichtern den Ladungstransport, was den Befund begünstigt (2 BE). Chlorid kann zusätzlich Oberflächenschichten beeinträchtigen. Kein sichtbarer Rost beweist nicht, dass absolut keine Metallauflösung stattfindet.'),
        part('fokus-korrosion-3', 'Formulieren', 'Sie für Modell I die anodische und kathodische Teilgleichung sowie die anschließende Bildung von Eisen(II)-hydroxid aus den Ionen. Erklären Sie kurz, warum Eisen(II)-hydroxid noch nicht mit dem endgültigen Rost gleichzusetzen ist.', 7, 'Nutzen Sie die neutrale Umgebung für die Sauerstoffreduktion. Trennen Sie Elektronenübertragung und anschließende Fällung.', 'Anode: Fe → Fe²⁺ + 2 e⁻ (2 BE). Kathode: O₂ + 2 H₂O + 4 e⁻ → 4 OH⁻ (2 BE). Fällung: Fe²⁺ + 2 OH⁻ → Fe(OH)₂ (2 BE). Durch weitere Oxidation mit Sauerstoff entstehen Eisen(III)-Verbindungen des Rosts; Fe(OH)₂ ist ein Zwischenprodukt (1 BE).'),
        part('fokus-korrosion-4', 'Vergleichen', 'Sie Modell I und II hinsichtlich anodischer Reaktion, reduziertem Teilchen und Produkt der kathodischen Reaktion. Formulieren Sie zusätzlich die kathodische Teilgleichung für Modell II.', 6, 'Stellen Sie die Modelle anhand derselben drei Kriterien gegenüber. Nutzen Sie H₃O⁺ oder die vereinfachte Schreibweise H⁺.', 'In beiden Modellen wird Eisen zu Fe²⁺ oxidiert (1 BE). In Modell I wird O₂ reduziert und OH⁻ gebildet (2 BE). In Modell II werden H₃O⁺ bzw. H⁺ reduziert; es entsteht H₂ (1 BE). Kathode in Modell II: 2 H₃O⁺ + 2 e⁻ → H₂ + 2 H₂O, alternativ 2 H⁺ + 2 e⁻ → H₂ (2 BE).'),
        part('fokus-korrosion-5', 'Beurteilen', 'Sie die Aussage: „Ohne Sauerstoff kann Eisen grundsätzlich nicht korrodieren.“ Beziehen Sie Material 2 und 3 ein.', 4, 'Prüfen Sie, ob ein Befund unter bestimmten Bedingungen eine allgemeine Aussage rechtfertigt.', 'Die allgemeine Aussage ist falsch (1 BE). B zeigt nur, dass unter den dortigen neutralen, sauerstofffreien Bedingungen kein sichtbarer Rost entstand (1 BE). In saurer Lösung können stattdessen H₃O⁺-Ionen Elektronen aufnehmen; Eisen wird auch ohne O₂ zu Fe²⁺ oxidiert (1 BE). Daher sind sichtbare Rostbildung und Korrosion als Metallzerstörung durch Reaktionen zu unterscheiden (1 BE).')
      ]
    },
    {
      id: 'fokus-korrosionsschutz', title: '4. Welcher Schutz eignet sich für Stahl? (25 BE)',
      shortTitle: 'Korrosionsschutz im Vergleich', image: '../../assets/korrosion.png',
      description: 'Lack, Zink, Zinn und Opferanoden unter Alltagsbedingungen beurteilen · 25 BE',
      context: 'Für eine Stahlkonstruktion im Außenbereich wird ein Schutz gesucht, der auch bei kleinen Kratzern wirkt. Bearbeiten Sie die Aufgaben mit Material 1 bis 3. Stahl wird vereinfacht als Eisen betrachtet.',
      materials: [
        text('Material 1: Beanspruchung und Schutzvarianten', 'Die Konstruktion ist häufig von einem neutralen, sauerstoffhaltigen Wasserfilm bedeckt. Kleine Kratzer bis zum Stahl lassen sich nicht sicher verhindern. Verglichen werden Lack, eine Zinkschicht und eine Zinnschicht. Die metallischen Überzüge berühren den Stahl elektrisch leitend. Im Modell wird eine mögliche Passivierung vernachlässigt. Eine intakte, dichte Schicht trennt den Stahl von der Umgebung.'),
        table('Material 2: Standardpotenziale als Orientierung', ['Redoxpaar', 'E° / V'], [['Zn²⁺/Zn', '−0,76'], ['Fe²⁺/Fe', '−0,44'], ['Sn²⁺/Sn', '−0,14']]),
        text('Einordnung zu Material 2', 'Die Angaben gelten unter Standardbedingungen. Für diese Aufgabe dienen sie zur qualitativen Einordnung der Metallpartner. Die tatsächliche Korrosionsgeschwindigkeit lässt sich daraus nicht berechnen. Im neutralen, belüfteten Wasserfilm wird an kathodischen Bereichen überwiegend gelöster Sauerstoff reduziert.'),
        text('Material 3: Opferanode an einem Stahlbehälter', 'Ein Stahlbehälter steht dauerhaft in neutralem, sauerstoffhaltigem Wasser. Ein Zinkblock kann mit einem Metalldraht elektrisch leitend am Behälter angeschlossen werden. Behälter und Zinkblock berühren dasselbe Wasser. Der Zinkblock wird regelmäßig kontrolliert und bei starkem Verbrauch ersetzt. Ein zweiter Vorschlag sieht vor, den Zinkblock ohne Draht und ohne direkten Metallkontakt nur daneben ins Wasser zu legen.')
      ],
      subtasks: [
        part('fokus-schutz-1', 'Erklären', 'Sie die Schutzwirkung einer intakten Lackschicht und die Folge eines Kratzers bis zum Stahl unter den Bedingungen aus Material 1.', 4, 'Unterscheiden Sie die Wirkung einer Barriere vom elektrochemischen Schutz an einer freigelegten Stelle.', 'Eine dichte Lackschicht verhindert den direkten Kontakt des Stahls mit Wasser und Sauerstoff (2 BE). Am Kratzer liegt Stahl im leitfähigen Wasserfilm frei und kann korrodieren (1 BE). Lack stellt keine Opferanode bereit und schützt die freigelegte Stelle daher nicht elektrochemisch (1 BE).'),
        part('fokus-schutz-2', 'Erläutern', 'Sie mithilfe von Material 1 und 2, warum eine Zinkschicht Stahl auch an einem kleinen Kratzer schützen kann. Formulieren Sie die Oxidationsgleichung und geben Sie die Elektronenflussrichtung an.', 6, 'Ordnen Sie die Metalle nach ihrer Oxidierbarkeit. Prüfen Sie, wo Elektronen entstehen und wohin sie gelangen.', 'Zink hat das negativere Standardpotenzial und wird im betrachteten Kontakt bevorzugt oxidiert (2 BE). Zn → Zn²⁺ + 2 e⁻ (2 BE). Elektronen fließen über den Metallkontakt vom Zink zum Stahl (1 BE). Der Stahl wird kathodisch geschützt; dort kann Sauerstoff reduziert werden, während die Eisenoxidation unterdrückt wird (1 BE). Der Schutz setzt ausreichendes Zink, leitenden Metallkontakt und einen gemeinsamen Elektrolyten voraus.'),
        part('fokus-schutz-3', 'Erklären', 'Sie, weshalb ein beschädigter Zinnüberzug die lokale Auflösung von Eisen begünstigen kann. Benennen Sie Anode und Kathode des Kontaktelements.', 5, 'Vergleichen Sie das Potenzial von Eisen mit dem des Überzugs. Die Reduktion im Wasserfilm muss keine Abscheidung des Überzugsmetalls sein.', 'Zinn ist nach Material 2 edler als Eisen (1 BE). Freiliegendes Eisen bildet die Anode und wird zu Fe²⁺ oxidiert (2 BE). Die Zinnoberfläche bildet einen kathodischen Bereich, an dem Sauerstoff reduziert wird (1 BE). Das Kontaktelement kann den örtlichen Eisenangriff am Kratzer verstärken, besonders bei kleiner Eisenfläche und großer kathodischer Fläche; eine konkrete Geschwindigkeit ergibt sich aus den Potenzialen nicht (1 BE).'),
        part('fokus-schutz-4', 'Beurteilen', 'Sie die beiden Vorschläge aus Material 3. Erläutern Sie dabei die Bedeutung des Metalldrahts, des gemeinsamen Wassers und des regelmäßigen Austauschs.', 6, 'Verfolgen Sie den geschlossenen Stromkreis und überlegen Sie, welches Material dabei verbraucht wird.', 'Der leitend angeschlossene Zinkblock ist geeignet: Zink wird als Opferanode oxidiert (1 BE). Über den Draht gelangen Elektronen zum Stahl und ermöglichen dessen kathodischen Schutz (2 BE). Das gemeinsame Wasser ermöglicht den ionischen Ladungstransport (1 BE). Ohne Draht bzw. Metallkontakt fehlt der Elektronenweg; bloße räumliche Nähe reicht nicht (1 BE). Zink wird verbraucht und muss ersetzt werden, bevor der Schutz ausfällt (1 BE).'),
        part('fokus-schutz-5', 'Empfehlen', 'Sie für die Konstruktion aus Material 1 eine der drei Schutzvarianten. Begründen Sie die Wahl anhand der Kratzfestigkeit des Schutzprinzips und nennen Sie eine Grenze Ihrer Empfehlung.', 4, 'Entscheiden Sie anhand der geforderten Wirkung bei Schäden. Verwechseln Sie die Härte der Schicht nicht mit ihrer Schutzwirkung nach einem Kratzer.', 'Eine Zinkschicht ist unter den genannten Bedingungen zu empfehlen (1 BE): Sie bietet eine Barriere und schützt kleine freigelegte Stellen zusätzlich elektrochemisch (1 BE). Lack verliert am Kratzer seine Barrierewirkung; Zinn kann dort Kontaktkorrosion des Eisens fördern (1 BE). Grenze: Zink wird verbraucht; große Schäden oder fehlender leitender Kontakt können den Schutz begrenzen. Regelmäßige Kontrolle bleibt notwendig (1 BE). Andere Vorschläge sind bei nachvollziehbarer Abwägung der vorgegebenen Bedingungen zu würdigen.')
      ]
    }
  ];
  tasks.forEach(task => {
    task.focusExam = true;
    task.subtasks.forEach((subtask, index) => { subtask.label = `${index + 1}.`; });
  });
  window.klausurTaskData.klausurTasks.push(...tasks);
})();
